l, r = 0, len(nums) - 1
while l < r:
    if good(nums[l], nums[r]):
        record(l, r)
    if should_move_left(nums[l], nums[r]):
        l += 1
    else:
        r -= 1

stack = []                      # indices still waiting
for i, x in enumerate(nums):
    while stack and nums[stack[-1]] < x:
        j = stack.pop()             # x resolves j
        answer[j] = i - j
    stack.append(i)

lo, hi = 0, len(nums) - 1     # the answer, if any, is in [lo, hi]
while lo <= hi:
    mid = (lo + hi) // 2
    if nums[mid] == target:
        return mid
    if nums[mid] < target:
        lo = mid + 1             # mid and everything left of it is too small
    else:
        hi = mid - 1             # mid and everything right of it is too big
return -1
